// Get all input items from the merge node
const items = $input.all();

// Initialize the result object
let result = {
  originalInput: {
    topic: "",
    originalText: ""
  },
  searchResults: "",
  newsResults: ""
};

// Temporary arrays to hold the data
let searchArray = [];
let newsArray = [];

// Process each item
for (let i = 0; i < items.length; i++) {
  const item = items[i].json;

  // Check if this item has the topic field (from Code node)
  if (item.topic && item.originalText) {
    result.originalInput.topic = item.topic;
    result.originalInput.originalText = item.originalText;
  }

  // Check if this item has organic search results
  if (item.organic && Array.isArray(item.organic)) {
    searchArray = item.organic.slice(0, 5).map(r => ({
      title: r.title,
      snippet: r.snippet
    }));
  }

  // Check if this item has news results
  if (item.news && Array.isArray(item.news)) {
    newsArray = item.news.slice(0, 5).map(r => ({
      title: r.title,
      snippet: r.snippet
    }));
  }
}

// Stringify the arrays with pretty formatting for better AI readability
result.searchResults = JSON.stringify(searchArray, null, 2);
result.newsResults = JSON.stringify(newsArray, null, 2);

// Return as a single item
return [{
  json: result
}];

// Get the input data from the previous node
const inputData = $input.all();

// Process each item
const outputData = inputData.map(item => {
  // Get the text content from the Gemini response
  const text = item.json.content.parts[0].text;

  // Extract the topic using regex
  const topicMatch = text.match(/topic:\s*(.+?)(?:\n|$)/i);

  // Get the topic value or return null if not found
  const topic = topicMatch ? topicMatch[1].trim() : null;

  return {
    json: {
      topic: topic,
      originalText: text  // Optional: include original text for reference
    }
  };
});

return outputData;

// Safely get the output string
let outputString = '';

if (items[0]?.output) {
  outputString = items[0].output;
} else if (items[0]?.json?.output) {
  outputString = items[0].json.output;
} else {
  throw new Error('No output found in input data');
}

// Try to extract JSON from various formats
let cleanJson = outputString;

// Check if wrapped in markdown code fences
const markdownMatch = outputString.match(/```(?:json)?\s*(\[[\s\S]*?\])\s*```/);
if (markdownMatch) {
  cleanJson = markdownMatch[1];
} else {
  // Try to find JSON array directly in the string
  const directMatch = outputString.match(/(\[[\s\S]*\])/);
  if (directMatch) {
    cleanJson = directMatch[1];
  }
}

// Remove any leading/trailing whitespace and potential BOM
cleanJson = cleanJson.trim().replace(/^\uFEFF/, '');

// Parse the cleaned JSON
let outputArr;
try {
  outputArr = JSON.parse(cleanJson);
} catch (e) {
  // If parsing fails, log the problematic string for debugging
  console.error('Failed to parse JSON. Raw output:', outputString);
  console.error('Cleaned JSON attempt:', cleanJson);
  throw new Error('Failed to parse AI agent output: ' + e.message + '\n\nRaw output: ' + outputString.substring(0, 500));
}

// Validate that we have an array
if (!Array.isArray(outputArr)) {
  throw new Error('Expected an array of platform content objects');
}

// Map each platform to a flat MongoDB document
return outputArr.map(entry => ({
  json: {
    platform: entry.platform,
    tone: entry.tone,
    content1: entry.content1?.text || '',
    quality_score1: entry.content1?.quality_score || 0,
    engagement_potential1: entry.content1?.engagement_potential || 0,
    human_likeness_score1: entry.content1?.human_likeness_score || 0,
    content2: entry.content2?.text || '',
    quality_score2: entry.content2?.quality_score || 0,
    engagement_potential2: entry.content2?.engagement_potential || 0,
    human_likeness_score2: entry.content2?.human_likeness_score || 0
  }
}));
